  "trigger": "New conversation (inbound) received",
  "conditions": [
    {
      "field": "subject",
      "operator": "contains any of",
      "values": ["Issue", "not able to upload", "error", "failed", "not uploading", "payment failed"]
    },
    {
      "field": "body",
      "operator": "contains any of",
      "values": ["issue", "not able to upload", "error", "failed", "not uploading", "payment failed"]
    }
  ],
  "logic": "OR",
  "actions": [
    {
      "type": "assign to",
